import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (name, tfm, pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))
changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv != av:
        changes.append(k + (bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append(k + (bv,))

print('CHANGES:')
if not changes:
    print('  None - fully version-neutral!')
else:
    for c in changes:
        print(f'  {c[0]:15} {c[1]:8} {c[2]:45} {c[3]} -> {c[4]}')
print(f'\nUNCHANGED: {len(unchanged)} entries')
